n = 19

def shortest_path_length(graph, start, end, max_len=5):
    """BFS to find shortest path length, up to max_len"""
    visited = {start: 0}
    queue = [start]
    while queue:
        node = queue.pop(0)
        dist = visited[node]
        if dist >= max_len:
            continue
        for neighbor in graph.get(node, set()):
            if neighbor == end:
                return dist + 1
            if neighbor not in visited:
                visited[neighbor] = dist + 1
                queue.append(neighbor)
    return None

def has_short_cycle(adj, max_cycle=6):
    """Check if graph has any cycle of length <= max_cycle"""
    for u in adj:
        for v in list(adj[u]):
            if u < v:
                adj[u].remove(v)
                adj[v].remove(u)
                path_len = shortest_path_length(adj, u, v, max_cycle - 1)
                adj[u].add(v)
                adj[v].add(u)
                if path_len is not None and path_len + 1 <= max_cycle:
                    return True, path_len + 1
    return False, None

def is_3_colorable(adj, n):
    colors = [-1] * n
    def backtrack(v):
        if v == n:
            return True
        used = set()
        for u in adj[v]:
            if colors[u] != -1:
                used.add(colors[u])
        for c in range(3):
            if c not in used:
                colors[v] = c
                if backtrack(v+1):
                    return True
                colors[v] = -1
        return False
    return backtrack(0), colors

